import{_ as e,o as t,c as n,ag as r}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-13（神经科学）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/neuroscience/science-daily-2026-10-13.md","filePath":"topics/neuroscience/science-daily-2026-10-13.md"}'),s={name:"topics/neuroscience/science-daily-2026-10-13.md"};function c(i,o,a,g,l,d){return t(),n("div",null,[...o[0]||(o[0]=[r('<h1 id="科学日报-·-2026-10-13-神经科学" tabindex="-1">科学日报 · 2026-10-13（神经科学） <a class="header-anchor" href="#科学日报-·-2026-10-13-神经科学" aria-label="Permalink to &quot;科学日报 · 2026-10-13（神经科学）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-13.md</code> — 第36期 ｜ 科学板块</p></blockquote><hr><h2 id="首次在人脑同步量化-lsd-的受体占据与血流效应-nature-neuroscience" tabindex="-1">首次在人脑同步量化 LSD 的受体占据与血流效应（Nature Neuroscience） <a class="header-anchor" href="#首次在人脑同步量化-lsd-的受体占据与血流效应-nature-neuroscience" aria-label="Permalink to &quot;首次在人脑同步量化 LSD 的受体占据与血流效应（Nature Neuroscience）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-13.md</code> ｜ DOI: 10.1038/s41593-026-02462-2</p></blockquote><ul><li>方法：<strong>同步 PET–MRI</strong>，在 <strong>7 名对剂量设盲</strong>的健康志愿者身上，同时测<strong>分子层面（受体占据）<strong>与</strong>血流动力学</strong>。</li><li>结果：LSD 以<strong>高亲和力占据 5-HT2A 受体</strong>；<strong>升高全局脑血流（CBF）与颈内动脉血流</strong>；<strong>降低全局功能连接</strong>，且<strong>连接下降与 CBF 升高呈负相关</strong>。</li><li>药效动力学：血浆药物浓度与主观体验之间出现<strong>逆时针滞后环</strong>——提示<strong>非典型</strong>机制（效应不简单跟随血药浓度）。</li><li>对照：另以 <strong>25 名裸盖菇素（psilocybin）<strong>受试者对比，凸显 LSD 与裸盖菇素的</strong>神经生理异同</strong>。</li><li>意义：<strong>首次在人体建立 LSD 的剂量—受体占据关系</strong>，为迷幻药物临床开发提供**靶点结合（target engagement）**的定量依据。</li><li>洞察（对本库 <code>neuroscience</code>）：<strong>&quot;占用同一受体 ≠ 相同脑效应&quot;</strong>——LSD 与裸盖菇素都打 5-HT2A，却能靠<strong>血流/连接</strong>区分。与&quot;<strong>同靶点、不同系统级药效</strong>&quot;母题一致：<strong>药效要看受体下游的系统响应，而不只是结合亲和力。</strong></li></ul><hr><h2 id="阿尔茨海默病的结构变异-fam193b-启动子里的-ccg-重复-nature-neuroscience" tabindex="-1">阿尔茨海默病的结构变异：FAM193B 启动子里的 CCG 重复（Nature Neuroscience） <a class="header-anchor" href="#阿尔茨海默病的结构变异-fam193b-启动子里的-ccg-重复-nature-neuroscience" aria-label="Permalink to &quot;阿尔茨海默病的结构变异：FAM193B 启动子里的 CCG 重复（Nature Neuroscience）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-13.md</code> ｜ DOI: 10.1038/s41593-026-02481-z</p></blockquote><ul><li>背景：AD 是<strong>多基因病</strong>，大量 <strong>SNP</strong> 已知，但**结构变异（SV）**的贡献不清楚。</li><li>数据：中国人群<strong>长读长（n = 11）+ 短读长（n = 3,190）<strong>测序 → 证明</strong>常见 SV 在 SNP 之外进一步贡献 AD 遗传度</strong>。</li><li>发现：<strong>FAM193B 启动子</strong>中一段<strong>扩张的 CCG 重复</strong>与 AD 风险<strong>全基因组显著</strong>相关（<strong>每增加 10 个重复 OR = 2.20，P = 5.5×10⁻¹³</strong>）。</li><li>机制：该重复<strong>升高 FAM193B 表达</strong>，并<strong>介导</strong>&quot;脑内 FAM193B 表达 ↔ AD 风险&quot;的<strong>多效关联</strong>。</li><li>功能：尸检人脑 + 培养神经元显示<strong>神经元 FAM193B 升高</strong>与 <strong>DNA 损伤 / 细胞死亡相关通路</strong>相关。</li><li>洞察（对本库 <code>neuroscience</code> / <code>biomedicine</code>）：<strong>致病变异不都在蛋白编码区</strong>——这次是<strong>启动子里的非编码短串联重复</strong>通过<strong>调控剂量</strong>致病。与 10-12 的 FAN1 功能缺失、波利尼西亚奠基者效应呼应：<strong>&quot;遗传风险&quot;越来越是&quot;调控剂量问题&quot;，而非&quot;蛋白坏没坏&quot;。</strong></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/neuroscience/index.md</code> ｜ 第36期 科学板块</p></blockquote><p>关键词：LSD、迷幻药、5-HT2A 受体、PET–MRI、受体占据、全局脑血流、颈内动脉血流、全局功能连接、逆时针滞后环、药效动力学、裸盖菇素、psilocybin、靶点结合；阿尔茨海默病、结构变异、SV、FAM193B、CCG 重复、启动子、长读长测序、多效关联、DNA 损伤、非编码短串联重复、调控剂量 关联：<code>topics/neuroscience/science-daily-2026-10-09.md</code>（回路/状态动力学：分裂吸引子航向记忆）、<code>topics/biomedicine/science-daily-2026-10-12.md</code>（多组学/调控层面疾病机制）、<code>topics/psychology/index.md</code>（意识/主观体验与脑生理的对应）</p>',13)])])}const q=e(s,[["render",c]]);export{p as __pageData,q as default};
